(async()=>{const f=document.querySelector("iframe"),w=f.contentWindow,d=f.contentDocument;f.style.width="1440px";const wait=()=>new Promise(r=>setTimeout(r,150));const parse=x=>{let m=x.match(/^rgba?\(([^)]+)\)/);return m?m[1].split(",").map(Number):null};const lum=c=>{let a=c.slice(0,3).map(x=>{x/=255;return x<=.04045?x/12.92:((x+.055)/1.055)**2.4});return .2126*a[0]+.7152*a[1]+.0722*a[2]};let out=[];for(const theme of ["dark","light"]){d.documentElement.dataset.theme=theme;for(let i=0;i<8;i++){let nav=d.querySelectorAll(".nav-item")[i];nav.click();await wait();let bad=[];for(const e of d.querySelectorAll("h1,h2,h3,p,button,label,small,th,td,span")){if(!e.getClientRects().length||e.disabled||!Array.from(e.childNodes).some(n=>n.nodeType===3&&n.textContent.trim()))continue;let style=w.getComputedStyle(e),fg=parse(style.color),p=e,bg;while(p){let c=parse(w.getComputedStyle(p).backgroundColor);if(c&&(c.length<4||c[3]===1)){bg=c;break}p=p.parentElement}if(!fg||!bg)continue;let a=lum(fg),b=lum(bg),ratio=(Math.max(a,b)+.05)/(Math.min(a,b)+.05),large=parseFloat(style.fontSize)>=24||(parseFloat(style.fontSize)>=18.66&&parseInt(style.fontWeight)>=700);if(ratio<(large?3:4.5))bad.push({text:e.textContent.trim().slice(0,28),ratio:+ratio.toFixed(2),fg:style.color,bg:w.getComputedStyle(p).backgroundColor})}out.push({theme,page:nav.textContent.trim(),count:bad.length,examples:bad.slice(0,4)})}}return out})()
